// TypeScript interfaces for OOTDay Fashion Assistant

// Export all new type definitions
export * from './types/enums'
export * from './types/localization-types'
export * from './types/product-types'

// Re-export FlatLayItem from image-types for use in ChatMessage
import type { FlatLayItem } from './types/image-types'
export type { FlatLayItem }

// Legacy interfaces maintained for backward compatibility
// These will gradually be replaced by EnhancedProduct
export interface OutfitRequest {
  query: string
  userId?: string
  context?: {
    occasion?: string
    weather?: string
    preferences?: string[]
  }
}

export interface OutfitResponse {
  outfits: Outfit[]
  conversationId: string
  suggestions: string[]
}

export interface Outfit {
  id: string
  title: string
  description: string
  totalPrice: number
  items: Product[]
  imageUrl?: string
}

/**
 * @deprecated Use EnhancedProduct from './types/product-types' instead
 * This interface is kept for backward compatibility
 */
export interface Product {
  sku: string
  name: string
  brand: string
  price: number
  imageUrl: string
  availability: "in_stock" | "low_stock" | "out_of_stock"
  storeLocations?: string[]
  onlineUrl?: string
  sizes?: string[]
  colors?: string[]
  category?: string // "Men", "Women", or other categories
  subCategory?: string // "Blazer", "Skirt", "Pants", etc.
  visualDescription?: string // For AI Image Generation prompt
  occasion?: string[] // For filtering
}

export interface ChatMessage {
  id: string
  content: string
  sender: "user" | "assistant"
  timestamp: Date
  outfits?: Outfit[]
  /** Image URL for generated outfit visualization (v3.1) */
  imageUrl?: string
  /** Base64-encoded image data (v3.1) */
  imageBase64?: string
  /** Outfit description used for image generation (v3.1) */
  outfitDescription?: string
  /** Image display mode: 'portrait' (3:4) or 'flat-lay' (1:1 square) (v4.0) */
  displayMode?: 'portrait' | 'flat-lay'
  /** Recommended items for flat-lay display (v4.0) */
  recommendedItems?: FlatLayItem[]
}

export interface ConversationStarter {
  id: string
  text: string
  category: string
}

export interface FilterState {
  gender?: 'all' | 'men' | 'women'
  occasion?: string[]  // ['work', 'casual', 'date', 'formal']
  priceRange?: { min: number; max: number }
  searchQuery?: string
}

'use client'

import { useState, useEffect } from 'react'
import { ChatHeader } from './ChatHeader'
import { ChatMessage } from './ChatMessage'
import { ChatInput } from './ChatInput'
import { QuickPrompts } from './QuickPrompts'
import { OutfitRecommendationCard } from './OutfitRecommendationCard'
import { InteractiveTestMode } from './InteractiveTestMode'
import { Button } from '@/components/ui/button'
import { PanelSizeControls } from '@/components/layout/PanelSizeControls'
import { useResizablePanelContext } from '@/components/layout/ResizablePanel'
import { Beaker } from 'lucide-react'
import type { ChatMessage as ChatMessageType, Outfit, FlatLayItem } from '@/lib/types'
import type { TestResult } from '@/lib/types/test-types'
import { getMockOutfitResponse } from '@/lib/mock-data'
import { exportResultsBoth } from '@/lib/test-result-exporter'
import type { SessionContext } from '@/lib/types/chat-types'
import { createSessionContext } from '@/lib/utils/session-context'
import { useUserProfile } from '@/lib/hooks/useUserProfile'

interface ChatAssistantProps {
  onViewOutfit: (outfit: Outfit) => void
}

export function ChatAssistant({ onViewOutfit }: ChatAssistantProps) {
  const [messages, setMessages] = useState<ChatMessageType[]>([])
  const [isTyping, setIsTyping] = useState(false)
  const [testMode, setTestMode] = useState(false)

  // v2.0: Session context for duplicate prevention
  const [sessionContext, setSessionContext] = useState<SessionContext>(() => createSessionContext())
  const [conversationId] = useState<string>(() => `conv-${Date.now()}`)

  // v2.4: User profile for gender preference
  const { profile } = useUserProfile()

  // v3.1: Image generation state (Customer Journey Step 4)
  const [generatingImage, setGeneratingImage] = useState(false)
  const [imageGenerationError, setImageGenerationError] = useState<string | null>(null)

  // v3.2: Initialize with Thai greeting message
  useEffect(() => {
    if (messages.length === 0) {
      const greeting: ChatMessageType = {
        id: 'greeting-initial',
        content: 'ฮ้ายฮายย👋 กำลังหาชุดไปไหนอยู่น้าา',
        sender: 'assistant',
        timestamp: new Date(),
      }
      setMessages([greeting])
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  // Get resize controls from ResizablePanel context (optional - only if in resizable panel)
  let panelWidth = 420
  let setPresetSize: ((size: number) => void) | undefined
  try {
    const context = useResizablePanelContext()
    panelWidth = context.panelWidth
    setPresetSize = context.setPresetSize
  } catch {
    // Not in a resizable panel context, that's okay
  }

  const isTestModeEnabled = process.env.NEXT_PUBLIC_ENABLE_TEST_MODE === 'true'

  const handleTestComplete = (result: TestResult) => {
    console.log('Test completed:', result)
  }

  const handleExportResults = (results: TestResult[]) => {
    exportResultsBoth(results)
  }

  const handleSendMessage = async (content: string) => {
    if (!content.trim()) return

    // Add user message
    const userMessage: ChatMessageType = {
      id: `user-${Date.now()}`,
      content: content.trim(),
      sender: 'user',
      timestamp: new Date(),
    }

    setMessages((prev) => [...prev, userMessage])
    setIsTyping(true)

    try {
      // Call real chat API
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: content.trim(),
          conversationHistory: messages.map((msg) => ({
            role: msg.sender === 'user' ? 'user' : 'assistant',
            content: msg.content,
          })),
          sessionContext, // v2.0: Send current session context
          conversationId, // v2.0: Send conversation ID
          userPreferences: {
            gender: profile?.gender as 'men' | 'women' | undefined,
            userName: profile?.userName,
            ageRange: profile?.ageRange,
            stylePreferences: profile?.stylePreferences,
          }, // v2.5: Pass detailed profile info
        }),
      })

      if (!response.ok) {
        throw new Error('Failed to get response from chat API')
      }

      const data = await response.json()

      // v2.0: Update session context if returned
      if (data.sessionContext) {
        setSessionContext(data.sessionContext)
        console.log(`[Chat] Session updated: ${data.sessionContext.recommendedProductIds?.length || 0} total products recommended`)
      }

      // Create AI response message (normal flow)
      const aiResponse: ChatMessageType = {
        id: `ai-${Date.now()}`,
        content: data.message || 'สวัสดีค่ะ! นี่คือคำแนะนำสำหรับคุณ',
        sender: 'assistant',
        timestamp: new Date(),
        outfits: data.outfits || [],
      }

      setMessages((prev) => [...prev, aiResponse])
      setIsTyping(false)

      // v3.1: Check if this is an image generation request (Auto or Manual)
      // v4.0: Updated to use flat-lay generation with recommended items
      if (data.imageRequest && (data.outfitDescription || (data.outfits && data.outfits.length > 0))) {
        console.log('[Chat] Image request detected, generating flat-lay image...')

        // Add AI acknowledgment message for auto-generation (UX Feedback)
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        // Generate image
        setGeneratingImage(true)
        setImageGenerationError(null)

        try {
          // v4.0: Extract FlatLayItem array from outfit items for flat-lay generation
          let flatLayItems: FlatLayItem[] = []
          let occasionContext: string | undefined

          if (data.outfits && data.outfits.length > 0) {
            const outfit = data.outfits[0]
            flatLayItems = outfit.items.slice(0, 5).map((item: any) => ({
              name: item.name,
              category: item.subCategory || item.category || 'Item',
              color: item.colors?.[0],
              visualDescription: item.visualDescription,
            }))
            occasionContext = outfit.description
          }

          // Determine UI Description (Thai)
          const uiDescription = (data.outfits && data.outfits.length > 0)
            ? data.outfits[0].description
            : "ภาพตัวอย่าง LOOKs จากชุดที่แนะนำ ✨"

          // Use flat-lay generation if we have items, otherwise fallback to regular outfit generation
          let imageResponse
          if (flatLayItems.length > 0) {
            imageResponse = await fetch('/api/generate-image', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
              },
              body: JSON.stringify({
                description: uiDescription, // Fallback description
                generationType: 'flat-lay',
                flatLayItems,
                occasionContext,
              }),
            })
          } else {
            // Fallback to regular outfit generation
            imageResponse = await fetch('/api/generate-image', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
              },
              body: JSON.stringify({
                description: data.outfitDescription || uiDescription,
              }),
            })
          }

          const imageData = await imageResponse.json()

          if (imageData.success && (imageData.imageUrl || imageData.imageBase64)) {
            const imageMessage: ChatMessageType = {
              id: `ai-image-${Date.now()}`,
              content: 'นี่คือภาพชุดที่เราคิด! ✨',
              sender: 'assistant',
              timestamp: new Date(),
              imageUrl: imageData.imageUrl,
              imageBase64: imageData.imageBase64,
              outfitDescription: uiDescription,
              displayMode: flatLayItems.length > 0 ? 'flat-lay' : 'portrait',
              recommendedItems: flatLayItems.length > 0 ? flatLayItems : undefined,
            }
            setMessages((prev) => [...prev, imageMessage])
          } else {
            // Image generation failed
            setImageGenerationError(imageData.message || 'ไม่สามารถสร้างภาพได้ กรุณาลองใหม่อีกครั้ง')

            // Only show error message if it was an explicit request (optional, here we show small error)
            const errorMessage: ChatMessageType = {
              id: `ai-error-${Date.now()}`,
              content: `ขออภัยค่ะ ${imageData.message || 'ไม่สามารถสร้างภาพได้ กรุณาลองใหม่อีกครั้ง'} 😊`,
              sender: 'assistant',
              timestamp: new Date(),
            }
            setMessages((prev) => [...prev, errorMessage])
          }
        } catch (error) {
          console.error('[Chat] Image generation error:', error)
          setImageGenerationError('เกิดข้อผิดพลาดในการสร้างภาพ')

          const errorMessage: ChatMessageType = {
            id: `ai-error-${Date.now()}`,
            content: 'ขออภัยค่ะ เกิดข้อผิดพลาดในการสร้างภาพ ลองใหม่อีกครั้งได้นะคะ 😊',
            sender: 'assistant',
            timestamp: new Date(),
          }
          setMessages((prev) => [...prev, errorMessage])
        } finally {
          setGeneratingImage(false)
        }
      }
    } catch (error) {
      console.error('Chat error:', error)

      // Fallback to mock response on error
      const aiResponse = getMockOutfitResponse(content)
      setMessages((prev) => [...prev, aiResponse])
      setIsTyping(false)

      // v3.2: Auto-trigger image generation for Mock/Fallback responses
      // v4.0: Updated to use flat-lay generation
      if (aiResponse.outfits && aiResponse.outfits.length > 0) {
        console.log('[Chat] Fallback: Auto-generating flat-lay image for mock response...')

        // Add acknowledgement
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        // Trigger generation
        setGeneratingImage(true)
        setImageGenerationError(null)

        try {
          // v4.0: Extract FlatLayItem array from outfit items
          const outfit = aiResponse.outfits[0]
          const flatLayItems: FlatLayItem[] = outfit.items.slice(0, 5).map((item: any) => ({
            name: item.name,
            category: item.subCategory || item.category || 'Item',
            color: item.colors?.[0],
            visualDescription: item.visualDescription,
          }))
          const occasionContext = outfit.description

          // Determine UI Description (Thai) from fallback response
          const uiDescription = aiResponse.outfits[0].description
            || "ภาพตัวอย่าง LOOKs จากชุดที่แนะนำ ✨"

          const imageResponse = await fetch('/api/generate-image', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              description: uiDescription,
              generationType: 'flat-lay',
              flatLayItems,
              occasionContext,
            }),
          })

          const imageData = await imageResponse.json()

          if (imageData.success && (imageData.imageUrl || imageData.imageBase64)) {
            const imageMessage: ChatMessageType = {
              id: `ai-image-${Date.now()}`,
              content: 'นี่คือภาพชุดที่เราคิด! ✨',
              sender: 'assistant',
              timestamp: new Date(),
              imageUrl: imageData.imageUrl,
              imageBase64: imageData.imageBase64,
              outfitDescription: uiDescription,
              displayMode: 'flat-lay',
              recommendedItems: flatLayItems,
            }
            setMessages((prev) => [...prev, imageMessage])
          } else {
            setImageGenerationError(imageData.message || 'Image generation failed')
            const errorMessage: ChatMessageType = {
              id: `ai-error-${Date.now()}`,
              content: `ขออภัยค่ะ ${imageData.message || 'ไม่สามารถสร้างภาพได้ (Mock Mode)'} 😊`,
              sender: 'assistant',
              timestamp: new Date(),
            }
            setMessages((prev) => [...prev, errorMessage])
          }
        } catch (err) {
          console.error('Fallback Image Gen Error:', err)
          setImageGenerationError('Failed to generate image')
          const errorMessage: ChatMessageType = {
            id: `ai-error-${Date.now()}`,
            content: 'ขออภัยค่ะ ไม่สามารถเชื่อมต่อกับบริการสร้างภาพได้',
            sender: 'assistant',
            timestamp: new Date(),
          }
          setMessages((prev) => [...prev, errorMessage])
        } finally {
          setGeneratingImage(false)
        }
      }
    }
  }

  return (
    <div className="h-full flex flex-col">
      {/* Test Mode Header */}
      {isTestModeEnabled && (
        <div className={`border-b px-4 py-3 flex items-center justify-between ${testMode ? 'bg-orange-50' : ''}`}>
          <div className="flex items-center gap-2">
            {testMode && (
              <span className="px-3 py-1 bg-orange-500 text-white font-bold rounded-md text-sm flex items-center gap-1">
                <Beaker className="w-4 h-4" />
                TEST MODE
              </span>
            )}
            <span className="text-sm text-muted-foreground">
              {testMode ? 'LLM Model Testing Interface' : 'OOTDay Stylist'}
            </span>
          </div>
          <div className="flex items-center gap-2">
            {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
            <Button
              size="sm"
              variant={testMode ? "primary" : "outline"}
              onClick={() => setTestMode(!testMode)}
              className={testMode ? "bg-orange-600 hover:bg-orange-700" : ""}
            >
              <Beaker className="w-4 h-4 mr-2" />
              {testMode ? 'Exit Test Mode' : 'Test Mode'}
            </Button>
          </div>
        </div>
      )}

      {/* Regular Header with resize controls */}
      {!isTestModeEnabled && !testMode && (
        <div className="border-b px-4 py-3 flex items-center justify-between">
          <span className="text-sm font-medium">OOTDay Stylist</span>
          {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
        </div>
      )}

      {/* Interactive Test Mode - Full Screen */}
      {testMode && isTestModeEnabled && (
        <div className="flex-1 overflow-hidden">
          <InteractiveTestMode onExport={handleExportResults} />
        </div>
      )}

      {!testMode && <ChatHeader />}

      {/* Messages Area */}
      {!testMode && (
        <div className="flex-1 overflow-y-auto px-4 py-3">
          {messages.length === 0 && (
            <div className="text-center py-8">
              <p className="text-sm text-muted-foreground leading-relaxed max-w-xs mx-auto">
                สวัสดีค่ะ! OOTDay Stylist พร้อมช่วยหาลุคที่ใช่สำหรับคุณค่ะ ✨
              </p>
            </div>
          )}

          {messages.map((message) => (
            <div key={message.id}>
              <ChatMessage message={message} />

              {/* Outfit recommendations */}
              {message.outfits && message.outfits.length > 0 && (
                <div className="ml-10 mt-2 space-y-2">
                  {message.outfits.map((outfit) => (
                    <OutfitRecommendationCard
                      key={outfit.id}
                      outfit={outfit}
                      onViewOutfit={onViewOutfit}
                    />
                  ))}
                </div>
              )}
            </div>
          ))}

          {isTyping && (
            <div className="flex justify-start">
              <div className="flex items-center gap-2 bg-gray-100 rounded-lg px-3 py-2">
                <div className="flex space-x-1">
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Quick Prompts */}
      {!testMode && <QuickPrompts onPromptClick={handleSendMessage} />}

      {/* Chat Input */}
      {!testMode && <ChatInput onSend={handleSendMessage} disabled={isTyping} />}
    </div>
  )
}

/**
 * LooksInspiration Component
 * Displays generated outfit images in chat interface (Customer Journey Step 4)
 *
 * Features:
 * - Loading state with skeleton animation
 * - Error state with retry functionality
 * - Success state with image display
 * - Click to expand/zoom with dialog
 * - Download functionality
 * - Mobile-responsive design
 * - WCAG 2.1 AA accessibility
 */

'use client';

import { useState } from 'react';
import Image from 'next/image';
import { Download, RefreshCw, ZoomIn, AlertCircle, Loader2 } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import type { LooksInspirationProps } from '@/lib/types/image-types';

export function LooksInspiration({
  outfitDescription,
  imageUrl,
  imageBase64,
  isLoading = false,
  error,
  onRetry,
  onGenerateAnother,
  onDownload,
  displayMode = 'portrait',
  recommendedItems,
  headerTitle,
}: LooksInspirationProps) {
  const [isZoomOpen, setIsZoomOpen] = useState(false);
  const [imageError, setImageError] = useState(false);

  // Determine image source (prefer URL over base64)
  const imageSrc = imageUrl || imageBase64;

  // Determine aspect ratio based on display mode
  const isFlatLay = displayMode === 'flat-lay';
  const aspectClass = isFlatLay ? 'aspect-square' : 'aspect-[3/4]';
  const itemCount = recommendedItems?.length || 0;

  /**
   * Handles image download
   */
  const handleDownload = () => {
    if (onDownload) {
      onDownload();
      return;
    }

    // Default download implementation
    if (!imageSrc) return;

    try {
      // Create download link
      const link = document.createElement('a');
      link.href = imageSrc;
      link.download = `ootday-outfit-${Date.now()}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (err) {
      console.error('[LooksInspiration] Download failed:', err);
    }
  };

  /**
   * Renders loading state
   */
  if (isLoading) {
    return (
      <Card className="max-w-md mx-auto my-4" role="status" aria-live="polite">
        <CardContent className="p-4">
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-sm text-gray-600">
              <Loader2 className="w-4 h-4 animate-spin" aria-hidden="true" />
              <span>กำลังสร้างภาพชุดของคุณ...</span>
            </div>
            <Skeleton className={`w-full rounded-lg ${isFlatLay ? 'aspect-square' : 'h-64'}`} />
            <div className="space-y-2">
              <Skeleton className="h-4 w-3/4" />
              <Skeleton className="h-4 w-1/2" />
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  /**
   * Renders error state
   */
  if (error || !imageSrc) {
    return (
      <Card className="max-w-md mx-auto my-4 border-red-200 bg-red-50" role="alert" aria-live="assertive">
        <CardContent className="p-4">
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-red-600">
              <AlertCircle className="w-5 h-5 flex-shrink-0" aria-hidden="true" />
              <div>
                <p className="font-medium text-sm">ไม่สามารถสร้างภาพได้</p>
                <p className="text-xs text-red-500 mt-1">
                  {error || 'เกิดข้อผิดพลาดในการสร้างภาพ กรุณาลองใหม่อีกครั้ง'}
                </p>
              </div>
            </div>

            {onRetry && (
              <Button
                onClick={onRetry}
                variant="outline"
                size="sm"
                className="w-full border-red-300 hover:bg-red-100"
                aria-label="Retry image generation"
              >
                <RefreshCw className="w-4 h-4 mr-2" aria-hidden="true" />
                ลองใหม่อีกครั้ง
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    );
  }

  /**
   * Renders success state with image
   */
  return (
    <>
      <Card className="max-w-md mx-auto my-4 overflow-hidden">
        <CardContent className="p-0">
          {/* LOOKs Header for flat-lay mode */}
          {isFlatLay && (
            <div className="px-4 pt-4 pb-2">
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="text-lg font-bold text-gray-900">
                    {headerTitle || 'LOOKs'}
                  </h3>
                  <p className="text-xs text-gray-500">Outfit Inspiration by OOTDay</p>
                </div>
                {itemCount > 0 && (
                  <span className="px-2 py-1 bg-primary/10 text-primary text-xs font-medium rounded-full">
                    {itemCount} ชิ้น
                  </span>
                )}
              </div>
            </div>
          )}

          {/* Image Display */}
          <div className="relative group">
            <div className={`relative w-full ${aspectClass} bg-gray-100`}>
              {!imageError ? (
                <Image
                  src={imageSrc}
                  alt={`Outfit visualization: ${outfitDescription}`}
                  fill
                  className={isFlatLay ? 'object-contain' : 'object-cover'}
                  sizes="(max-width: 768px) 100vw, 500px"
                  onError={() => setImageError(true)}
                  priority
                />
              ) : (
                <div className="absolute inset-0 flex items-center justify-center text-gray-400">
                  <AlertCircle className="w-12 h-12" />
                </div>
              )}
            </div>

            {/* Zoom Button Overlay */}
            <button
              onClick={() => setIsZoomOpen(true)}
              className="absolute inset-0 bg-black/0 hover:bg-black/10 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100 focus:opacity-100 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-inset"
              aria-label="Zoom image"
            >
              <div className="bg-white/90 rounded-full p-2">
                <ZoomIn className="w-6 h-6 text-gray-700" aria-hidden="true" />
              </div>
            </button>
          </div>

          {/* Image Caption and Actions */}
          <div className="p-4 space-y-3">
            {/* Caption - show different style for flat-lay */}
            <div>
              {!isFlatLay && (
                <p className="text-sm font-medium text-gray-900">Looks Inspiration 💫</p>
              )}
              <p className={`text-xs text-gray-600 ${!isFlatLay ? 'mt-1' : ''}`}>
                {outfitDescription}
              </p>
            </div>

            {/* Action Buttons */}
            <div className="flex gap-2">
              {/* Download Button */}
              <Button
                onClick={handleDownload}
                variant="outline"
                size="sm"
                className="flex-1"
                aria-label="Download outfit image"
              >
                <Download className="w-4 h-4 mr-2" aria-hidden="true" />
                ดาวน์โหลด
              </Button>

              {/* Generate Another Button (Optional) */}
              {onGenerateAnother && (
                <Button
                  onClick={onGenerateAnother}
                  variant="outline"
                  size="sm"
                  className="flex-1"
                  aria-label="Generate another outfit variation"
                >
                  <RefreshCw className="w-4 h-4 mr-2" aria-hidden="true" />
                  สร้างอีกครั้ง
                </Button>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Zoom Dialog */}
      <Dialog open={isZoomOpen} onOpenChange={setIsZoomOpen}>
        <DialogContent className="max-w-4xl w-full max-h-[90vh] overflow-auto">
          <DialogHeader>
            <DialogTitle className="sr-only">
              Outfit image - {outfitDescription}
            </DialogTitle>
          </DialogHeader>

          <div className="relative w-full">
            <div className={`relative w-full ${isFlatLay ? 'aspect-square' : 'aspect-[3/4]'} max-h-[80vh] bg-gray-100 rounded-lg overflow-hidden`}>
              {!imageError ? (
                <Image
                  src={imageSrc}
                  alt={`Full size outfit visualization: ${outfitDescription}`}
                  fill
                  className="object-contain"
                  sizes="(max-width: 1024px) 100vw, 1024px"
                  priority
                />
              ) : (
                <div className="absolute inset-0 flex items-center justify-center text-gray-400">
                  <AlertCircle className="w-16 h-16" />
                </div>
              )}
            </div>

            {/* Caption in Dialog */}
            <div className="mt-4">
              {isFlatLay && (
                <div className="flex items-center gap-2 mb-2">
                  <span className="text-lg font-bold text-gray-900">
                    {headerTitle || 'LOOKs'}
                  </span>
                  {itemCount > 0 && (
                    <span className="px-2 py-1 bg-primary/10 text-primary text-xs font-medium rounded-full">
                      {itemCount} ชิ้น
                    </span>
                  )}
                </div>
              )}
              <p className="text-sm font-medium text-gray-900">{outfitDescription}</p>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

'use client'

import { Sparkles } from 'lucide-react'
import type { ChatMessage as ChatMessageType } from '@/lib/types'
import { LooksInspiration } from './LooksInspiration'

interface ChatMessageProps {
  message: ChatMessageType
}

export function ChatMessage({ message }: ChatMessageProps) {
  const isUser = message.sender === 'user'
  const hasImage = !!(message.imageUrl || message.imageBase64)

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    })
  }

  // Render image message (v3.1 - Customer Journey Step 4)
  // v4.0: Updated to pass displayMode and recommendedItems for flat-lay support
  if (hasImage && !isUser) {
    return (
      <div className="flex justify-start mb-3">
        <div className="flex items-start gap-2 w-full max-w-md">
          <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center flex-shrink-0 mt-1">
            <Sparkles className="w-4 h-4 text-white" />
          </div>

          <div className="flex-1">
            <LooksInspiration
              outfitDescription={message.outfitDescription || 'Outfit visualization'}
              imageUrl={message.imageUrl}
              imageBase64={message.imageBase64}
              isLoading={false}
              displayMode={message.displayMode || 'portrait'}
              recommendedItems={message.recommendedItems}
            />
          </div>
        </div>
      </div>
    )
  }

  // Render normal text message
  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} mb-3`}>
      <div className={`flex items-start gap-2 max-w-[80%]`}>
        {!isUser && (
          <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center flex-shrink-0 mt-1">
            <Sparkles className="w-4 h-4 text-white" />
          </div>
        )}

        <div
          className={`rounded-lg px-3 py-2 shadow-sm ${
            isUser
              ? 'bg-[var(--chat-user)] text-foreground ml-auto'
              : 'bg-[var(--chat-assistant)] text-foreground mr-auto border border-border'
          }`}
        >
          <p className="text-sm">{message.content}</p>
          <p className={`text-xs mt-1 text-muted-foreground`}>
            {formatTime(message.timestamp)}
          </p>
        </div>
      </div>
    </div>
  )
}

